ALTER TABLE `task_items` ADD `start_date` text CONSTRAINT `task_start_date_valid` CHECK(`start_date` IS NULL OR (length(`start_date`) = 10 AND `start_date` GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]' AND substr(`start_date`,1,4) <> '0000' AND date(`start_date`) IS NOT NULL AND date(`start_date`) = `start_date`)) CONSTRAINT `task_date_range_valid` CHECK(`start_date` IS NULL OR `due_date` IS NULL OR `start_date` <= `due_date`);
